// https://github.com/epibyte/p5-epi-colors
const { EpiColors } = EpiColorsPckg;
let epiColors;

function setup() {
	createCanvas(S=~~(min(innerWidth, innerHeight)*0.95), S);
	frameRate(30);

	epiColors = new EpiColors();
	epiColors.getRandomPalette(true);

	noiseSeed(~~random(7654321));
	loop();
}

function draw() {
	stroke(EpiColors.getColor(epiColors.BG, 64));
	strokeWeight(1);
	background(epiColors.BG);

	const PAD = S * 0.2;

	for (let y = PAD; y < height + PAD; y += PAD/5) {
		fill(map(y, 0, height, 50, 200))
		const f = map(y, PAD, height+PAD, 0, 1);
		// const clr = lerpColor(epiColors.palette[0], epiColors.palette[1], 1-f);
		const clr = epiColors.getLerpedColorFromPalette(f/2); // just use half of palette
		fill(clr);

		beginShape();
		vertex(0, height+y);

		const ny = noise(5 * y / height);
		const cx = ny * width;
		// console.log(ny)
		for (let x = 0; x < width; x += width * 0.01) {
			const a = map(x, 0, width, HALF_PI, TWO_PI + HALF_PI) + (ny-0.5)*4;
			const n = noise(x / width * 10, y / height * 10, frameCount/1500);
			const d = map(abs(cx - x), 0, width, 1, 0.1)
			const yy = sin(a) * S/4 * n /* * d */ + y;
			vertex(x, yy);
		}

		vertex(width, height+y);
		endShape();
	}

	strokeWeight(8);
	stroke(epiColors.FG);
	noFill();
	rect(4, 4, width-8, height-8);

	// // noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton.left && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}
